  openTools(){this.app.openModal('Drawing tools',`<div class="panel-toolbar"><input id="tools-filter" placeholder="Search lines, Fibonacci, patterns…" class="full-width">${button('Object manager','objects')}</div><div class="tool-catalog">${Object.entries(DRAWING_TOOLS).map(([id,d])=>`<button class="tool-choice" data-v2="choose-tool" data-tool-type="${id}"><b>${esc(d.name)}</b><small>${esc(d.category)} · ${d.points||'freeform'} anchors</small></button>`).join('')}</div>${note('Two anchors: drag or click–click. Three or more: click each anchor. Polyline: double-click to finish. Brush: drag. Ctrl/Cmd+C and V copy/paste selected drawings.')}`);}
